modes.detail:
// ============ 先看不用环会怎样（假溢出） ============
//
// 假设数组长度 5，一直"入队—出队"：
//
//   出队 3 次之后：
//        ┌────┬────┬────┬────┬────┐
//        │ __ │ __ │ __ │ 40 │ 50 │      front = 3, rear = 5
//        └────┴────┴────┴────┴────┘
//          ↑ 空着三个格子，但 rear 已经到头了
//
// 明明还有空间，却再也放不进新元素 —— 这就是**假溢出**。
// 真溢出是"数组真满了"，假溢出是"rear 撞墙了但前面空着"。
//
// ============ 用环解决 ============
//
// 让下标走到末尾之后回到 0：`(rear + 1) % MAXSIZE`
//
//        ┌────┬────┬────┬────┬────┐
//        │ 60 │ 70 │ __ │ 40 │ 50 │
//        └────┴────┴────┴────┴────┘
//                 ↑         ↑
//              rear = 2   front = 3
//
// 逻辑上是这样一圈（下标 0 紧接在 4 后面）：
//
//              0 ── 1 ── 2
//              │         │
//              4 ── 3 ───┘
//
// ============ 约定（务必记牢） ============
//
//   front 指向**队头元素本身**
//   rear  指向**队尾元素的下一个位置**（也就是下次入队该放哪）
//
//   front == rear                    →  队空
//   (rear + 1) % MAXSIZE == front    →  队满
//
// 注意队满的写法：它故意"浪费一个格子"，让队满和队空能区分开。
// 否则 front == rear 既可能是空也可能是满 —— 那就没法判断了。

// 元素类型
typedef int ElemType;

// 队列容量：实际最多只能放 MAXSIZE-1 个元素（为了区分空和满）
#define MAXSIZE 10

// 状态码
#define OK 1
#define ERROR 0

// 返回值类型
typedef int Status;

// 循环队列
typedef struct
{
// 连续内存，当成环来用
    ElemType data[MAXSIZE];
// 队头元素的下标
    int front;
// 队尾元素的下一个位置
    int rear;
} Queue;

