// ============ 出队 ============
//
//   出队前： 10  20  30  __  __      front = 0, rear = 3
//
//   ① e = data[0] = 10
//   ② front = (0+1) % 5 = 1
//
//   出队后： 10  20  30  __  __      front = 1, rear = 3
//             ↑
//        10 还在数组里，但已经不属于这张队列
//
// 和栈一样：**出队不擦数据，只是把 front 往前挪**。
// 空出来的格子不会被浪费 —— 等 rear 绕回来时会重新用它，
// 这正是循环队列比普通顺序队列强的地方。
//
// ============ 队空判断 ============
// front == rear 就是空。出队前必须判，否则读到的是早就出队的数据，
// 或者干脆是没初始化过的垃圾值。

// 出队，元素由 e 带回
Status DeQueue(Queue *Q, ElemType *e)
{
// 先判空
    if (Q->front == Q->rear)
    {
        return ERROR;
    }

// 取走队头元素
    *e = Q->data[Q->front];

// front 绕环前进一格
    Q->front = (Q->front + 1) % MAXSIZE;

// 成功
    return OK;
}

