modes.detail:
// ============ 这一节最该亲眼看到的一幕 ============
//
// 普通顺序队列只要出队几次，rear 就到头了，明明前面空着却放不进去。
// 循环队列跑下面这段"入队一个再出队一个"的循环 100 次，
// 每次都有位置 —— rear 和 front 会一起绕圈，永远不会撞墙。
//
// 打印出 front 和 rear 的变化过程，你会看到它们一次次从末尾跳回 0。

// 打印队列内容（从 front 开始，按逻辑顺序）
// 注意不能简单地 for (i = 0; i < MAXSIZE; i++)：
// 环里的元素可能"绕过弯"，必须从 front 出发绕圈走。
static void PrintQueue(const char *tag, Queue Q)
{
    int i;
    int n = (Q.rear - Q.front + MAXSIZE) % MAXSIZE;   /* 元素个数 */

    printf("%s front=%d rear=%d 共%d个 : ", tag, Q.front, Q.rear, n);
    for (i = 0; i < n; i++)
    {
        printf("%d ", Q.data[(Q.front + i) % MAXSIZE]);
    }
    printf("\n");
}

// 主函数
int main(void)
{
// 定义队列
    Queue Q;
// 出口参数
    ElemType e;
// 循环用
    int i;

// 初始化
    InitQueue(&Q);
    PrintQueue("初始化后:", Q);

// 入队 10 20 30
    EnQueue(&Q, 10);
    EnQueue(&Q, 20);
    EnQueue(&Q, 30);
    PrintQueue("入队 10 20 30 后:", Q);

// 出队一个 —— 应该是最先进入的 10
    if (DeQueue(&Q, &e) == OK)
    {
        printf("出队一个 -> %d（最先进去的最先出来）\n", e);
    }
    PrintQueue("出队后:", Q);

// 反复入队到满，看看到底能装几个
// 把 MAXSIZE 个全塞进去是不行的 —— 会留一个空位用来区分空和满。
    i = 0;
    while (EnQueue(&Q, 100 + i) == OK)
    {
        i++;
    }
    printf("最多装下 %d 个（MAXSIZE=%d，故意留一格）\n", i, MAXSIZE);
    PrintQueue("装满后:", Q);

// 关键一幕：边进边出跑很多次，验证不会假溢出
// 普通顺序队列跑到这里早就"溢"了，循环队列能一直跑下去。
    for (i = 0; i < 100; i++)
    {
        DeQueue(&Q, &e);
        EnQueue(&Q, i);
    }
    printf("边进边出 100 次之后：\n");
    PrintQueue("  当前状态:", Q);
    printf("  front 和 rear 都绕回小下标了 —— 这就是环的功劳\n");

// 正常结束
    return 0;
}

